namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public int TotalStars { get; set; }
    public int RatingCount { get; set; }

    public double AverageRating => RatingCount > 0 ? (double)TotalStars / RatingCount : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = "";
    public string Icon { get; set; } = "";
    public string Description { get; set; } = "";
}

using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class SubmitRecipeModel
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title cannot exceed 100 characters.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = "";

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = "";
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public static readonly List<RecipeCategory> Categories =
    [
        new() { Name = "Breakfast", Icon = "🥞", Description = "Start your day with delicious morning meals" },
        new() { Name = "Lunch", Icon = "🥗", Description = "Midday meals to keep you going" },
        new() { Name = "Dinner", Icon = "🍝", Description = "Hearty evening recipes for the whole family" },
        new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats and indulgent bakes" },
        new() { Name = "Snacks", Icon = "🍿", Description = "Quick bites for any time of day" },
        new() { Name = "Drinks", Icon = "🍹", Description = "Refreshing beverages and cocktails" },
    ];

    public RecipeService()
    {
        _recipes =
        [
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1½ cups milk\n2 tbsp butter\n2 tbsp sugar\n1 tbsp baking powder\nPinch of salt",
                Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs, milk, and melted butter together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a griddle over medium heat and grease lightly.\n5. Pour ¼ cup batter per pancake. Flip when bubbles form.\n6. Serve with maple syrup and fresh berries.",
                TotalStars = 14, RatingCount = 3 },
            new() { Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\n½ cup croutons\n¼ cup parmesan cheese\nCaesar dressing\nLemon juice",
                Steps = "1. Wash and chop romaine lettuce.\n2. Toss with Caesar dressing.\n3. Add croutons and shaved parmesan.\n4. Squeeze fresh lemon juice on top.\n5. Serve immediately.",
                TotalStars = 8, RatingCount = 2 },
            new() { Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Ingredients = "400g spaghetti\n500g ground beef\n1 onion\n3 cloves garlic\n800g canned tomatoes\n2 tbsp tomato paste\nFresh basil\nOlive oil\nSalt and pepper",
                Steps = "1. Cook spaghetti according to package directions.\n2. Sauté diced onion and garlic in olive oil.\n3. Add ground beef and brown thoroughly.\n4. Stir in canned tomatoes and tomato paste.\n5. Simmer for 20 minutes, season to taste.\n6. Serve sauce over spaghetti, garnish with basil.",
                TotalStars = 20, RatingCount = 4 },
            new() { Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "200g dark chocolate\n100g butter\n3 eggs\n100g sugar\n50g flour",
                Steps = "1. Preheat oven to 220°C (425°F).\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until fluffy.\n4. Fold chocolate mixture into eggs, then fold in flour.\n5. Pour into greased ramekins.\n6. Bake for 12 minutes — centers should be soft.\n7. Invert onto plates and serve immediately.",
                TotalStars = 10, RatingCount = 2 },
            new() { Id = 5, Title = "Trail Mix Energy Bites", Category = "Snacks",
                Ingredients = "1 cup oats\n½ cup peanut butter\n⅓ cup honey\n½ cup chocolate chips\n½ cup mixed nuts\n1 tsp vanilla",
                Steps = "1. Mix all ingredients in a bowl.\n2. Refrigerate for 30 minutes.\n3. Roll into 1-inch balls.\n4. Store in the refrigerator for up to a week.",
                TotalStars = 5, RatingCount = 1 },
            new() { Id = 6, Title = "Mango Smoothie", Category = "Drinks",
                Ingredients = "1 ripe mango\n1 banana\n1 cup yogurt\n½ cup orange juice\nIce cubes",
                Steps = "1. Peel and chop the mango.\n2. Add all ingredients to a blender.\n3. Blend until smooth.\n4. Pour into a glass and enjoy.",
                TotalStars = 9, RatingCount = 2 },
        ];
        _nextId = 7;
    }

    public IReadOnlyList<RecipeCategory> GetCategories() => Categories;

    public IReadOnlyList<Recipe> GetByCategory(string category)
        => _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalStars += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(SubmitRecipeModel model)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps,
        });
    }
}

