@page "/category/{CategoryName}"
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<h2>@_category?.Icon @CategoryName Recipes</h2>

@if (_recipes.Count == 0)
{
    <div class="alert alert-info mt-3">No recipes in this category yet. Be the first to <a href="submit">submit one</a>!</div>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="text-muted mb-2">
                            @if (recipe.RatingCount > 0)
                            {
                                <span>⭐ @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link mt-2">← Back to categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = "";

    private RecipeCategory? _category;
    private IReadOnlyList<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _category = RecipeService.GetCategories().FirstOrDefault(c => c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase));
        _recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (_recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-link">← Back to home</a>
}
else
{
    <div class="mb-3">
        <a href="category/@_recipe.Category" class="btn btn-link px-0">← Back to @_recipe.Category</a>
    </div>

    <h2>@_recipe.Title</h2>
    <span class="badge bg-secondary mb-3">@_recipe.Category</span>

    <div class="card mb-4">
        <div class="card-header"><strong>🥘 Ingredients</strong></div>
        <div class="card-body">
            <ul class="mb-0">
                @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-header"><strong>📝 Steps</strong></div>
        <div class="card-body">
            @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p class="mb-1">@step</p>
            }
        </div>
    </div>

    <StarRating RecipeId="_recipe.Id" CurrentAverage="_recipe.AverageRating" CurrentCount="_recipe.RatingCount" />
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(RecipeId);
    }
}

@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="card">
    <div class="card-body">
        <h5 class="card-title">Rate this recipe</h5>
        <div class="mb-2" style="font-size: 1.8rem; cursor: pointer;">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <span @onclick="() => SubmitRating(star)"
                      @onmouseover="() => _hoverStar = star"
                      @onmouseout="() => _hoverStar = 0"
                      style="color: @(star <= (_hoverStar > 0 ? _hoverStar : _selectedStar) ? "#ffc107" : "#ccc")">
                    ★
                </span>
            }
        </div>

        @if (_submitted)
        {
            <div class="alert alert-success py-2">
                Thanks for rating! You gave @_selectedStar star@(_selectedStar != 1 ? "s" : "").
                <br />Average: ⭐ @_average.ToString("0.0") (@_count ratings)
            </div>
        }
        else
        {
            <p class="text-muted mb-0">
                @if (CurrentCount > 0)
                {
                    <span>⭐ @CurrentAverage.ToString("0.0") (@CurrentCount ratings) — Click a star to rate</span>
                }
                else
                {
                    <span>Be the first to rate this recipe!</span>
                }
            </p>
        }
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int CurrentCount { get; set; }

    private int _hoverStar;
    private int _selectedStar;
    private bool _submitted;
    private double _average;
    private int _count;

    private void SubmitRating(int stars)
    {
        if (_submitted) return;

        _selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            _average = recipe.AverageRating;
            _count = recipe.RatingCount;
        }

        _submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h2>📝 Submit a Recipe</h2>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "<strong>@_model.Title</strong>" has been added.
        <a href="category/@_model.Category">View it in @_model.Category</a>.
    </div>
    <button class="btn btn-primary" @onclick="ResetForm">Submit another</button>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category" class="form-select">
                <option value="">— Select a category —</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Icon @cat.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="5"
                           placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="6"
                           placeholder="1. Preheat oven to 350°F&#10;2. Mix ingredients&#10;3. Bake for 30 minutes" />
            <ValidationMessage For="() => _model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
        <a href="/" class="btn btn-link">Cancel</a>
    </EditForm>
}

@code {
    private SubmitRecipeModel _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(_model);
        _submitted = true;
    }

    private void ResetForm()
    {
        _model = new();
        _submitted = false;
    }
}

